                 atomic_with_ghost!(
                 &self.rc => load();
                 returning res;
                 ghost g =>
             {
                 if res == 0 {
                     let tracked tok = match token { Option::Some(t) => t, Option::None => proof_from_false() };
                     let tracked x = self.inst.borrow().acquire_exc_end(&g, tok);
                     token = None;
                     let tracked (_, Tracked(perm), Tracked(exc_handle)) = x;
                     perm_opt = Some(perm);
                     handle_opt = Some(exc_handle);
                 }
             });

